import { colors, focusRing, radius } from "@shadcn-nsh/theme";
import type { JSX } from "nsh";
import { cleanup, context, Text, View } from "nsh";
import {
  Combobox as BaseCombobox,
  type OpenChangeReason,
  type SelectEntry,
  type SelectItem as SelectItemData,
} from "nsh/base";

import {
  createItemRegistry,
  createTriggerSlot,
  type ItemRegistry,
  type TriggerSlot,
} from "./lib/open-state";
import { popupBackdrop, popupSurface } from "./lib/popup-surface";

export type { SelectItemData, SelectEntry };

/** Composition root for `nsh/base` Combobox: value/open state + item registry + trigger slot. */
export type ComboboxProps = {
  multiple?: boolean;
  value?: string[] | null;
  defaultValue?: string[];
  open?: boolean | null;
  defaultOpen?: boolean;
  cleanable?: boolean;
  disabled?: boolean;
  placeholder?: string;
  accessibilityLabel?: string | null;
  empty?: JSX.Element;
  children?: JSX.Element;
  onChange?: (event: { value: string[] }) => void;
  onOpenChange?: (event: { open: boolean; reason: OpenChangeReason }) => void;
};

type ComboboxRootProps = ComboboxProps;

type ComboboxContextValue = {
  items: ItemRegistry<SelectItemData>;
  trigger: TriggerSlot;
  empty: TriggerSlot;
  value: () => string[] | null | undefined;
  placeholder: () => string;
  disabled: () => boolean | undefined;
  root: ComboboxRootProps;
};

const ComboboxContext = context<ComboboxContextValue | null>(null);

function useCombobox() {
  const ctx = ComboboxContext();
  if (!ctx) throw new Error("Combobox parts must be used within <Combobox>");
  return ctx;
}

function defaultTrigger(ctx: ComboboxContextValue) {
  const label = () => {
    const values = ctx.value() ?? [];
    if (values.length === 0) return ctx.placeholder();
    return values.map((v) => ctx.items.items().find((i) => i.value === v)?.title ?? v).join(", ");
  };

  return (
    <View
      style={{
        height: 36,
        minWidth: 180,
        paddingHorizontal: 12,
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 8,
        borderRadius: radius.control,
        borderWidth: 1,
        borderColor: colors.input,
        backgroundColor: colors.background,
        opacity: ctx.disabled() ? 0.5 : 1,
      }}
    >
      <Text
        style={{
          flex: 1,
          fontSize: 14,
          color: (ctx.value()?.length ?? 0) === 0 ? colors.mutedForeground : colors.foreground,
        }}
      >
        {label()}
      </Text>
      <Text style={{ fontSize: 12, color: colors.mutedForeground }}>▾</Text>
    </View>
  );
}

function StyledCombobox(props: {
  items: SelectItemData[];
  multiple?: boolean;
  value?: string[] | null;
  defaultValue?: string[];
  open?: boolean | null;
  defaultOpen?: boolean;
  cleanable?: boolean;
  disabled?: boolean;
  placeholder?: string;
  accessibilityLabel?: string | null;
  trigger?: JSX.Element;
  empty?: JSX.Element;
  onChange?: (event: { value: string[] }) => void;
  onOpenChange?: (event: { open: boolean; reason: OpenChangeReason }) => void;
}) {
  const label = () => {
    const values = props.value ?? [];
    if (values.length === 0) return props.placeholder ?? "Choose…";
    return values.map((v) => props.items.find((i) => i.value === v)?.title ?? v).join(", ");
  };

  const trigger = props.trigger ?? (
    <View
      style={{
        height: 36,
        minWidth: 180,
        paddingHorizontal: 12,
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 8,
        borderRadius: radius.control,
        borderWidth: 1,
        borderColor: colors.input,
        backgroundColor: colors.background,
        opacity: props.disabled ? 0.5 : 1,
      }}
    >
      <Text
        style={{
          flex: 1,
          fontSize: 14,
          color: (props.value?.length ?? 0) === 0 ? colors.mutedForeground : colors.foreground,
        }}
      >
        {label()}
      </Text>
      <Text style={{ fontSize: 12, color: colors.mutedForeground }}>▾</Text>
    </View>
  );

  return (
    <BaseCombobox
      items={props.items}
      multiple={props.multiple}
      value={props.value}
      defaultValue={props.defaultValue}
      open={props.open}
      defaultOpen={props.defaultOpen}
      cleanable={props.cleanable}
      disabled={props.disabled}
      accessibilityLabel={props.accessibilityLabel}
      offset={4}
      placeholder={props.placeholder}
      triggerButton={trigger}
      empty={props.empty}
      onChange={props.onChange}
      onOpenChange={props.onOpenChange}
      popupStyle={popupSurface()}
      backdropStyle={popupBackdrop()}
      listStyle={{ maxHeight: 240 }}
      itemStyle={{
        height: 32,
        paddingHorizontal: 8,
        borderRadius: 6,
        fontSize: 14,
        color: colors.foreground,
      }}
      inputStyle={{
        height: 36,
        paddingHorizontal: 12,
        borderRadius: radius.control,
        borderWidth: 1,
        borderColor: colors.input,
        backgroundColor: colors.background,
        fontSize: 14,
        color: colors.foreground,
        ...focusRing(),
      }}
      renderItem={(item: SelectEntry) => {
        const selected = (props.value ?? []).includes(item.value);
        return (
          <View
            style={{
              height: 32,
              paddingHorizontal: 8,
              borderRadius: 6,
              flexDirection: "row",
              alignItems: "center",
              justifyContent: "space-between",
              opacity: item.disabled ? 0.4 : 1,
            }}
          >
            <Text
              style={{
                fontSize: 14,
                fontWeight: selected ? "600" : "400",
                color: colors.foreground,
              }}
            >
              {item.title}
            </Text>
            {selected ? <Text style={{ fontSize: 12, color: colors.primary }}>✓</Text> : null}
          </View>
        );
      }}
    />
  );
}

export function Combobox(props: ComboboxRootProps) {
  const items = createItemRegistry<SelectItemData>([]);
  const trigger = createTriggerSlot();
  const empty = createTriggerSlot();
  const ctx: ComboboxContextValue = {
    items,
    trigger,
    empty,
    value: () => props.value,
    placeholder: () => props.placeholder ?? "Choose…",
    disabled: () => props.disabled,
    root: props,
  };

  return <ComboboxContext.Provider value={ctx}>{props.children}</ComboboxContext.Provider>;
}

export function ComboboxTrigger(props: { children?: JSX.Element }) {
  const ctx = useCombobox();
  ctx.trigger.set(() => (
    <View
      style={{
        height: 36,
        minWidth: 180,
        paddingHorizontal: 12,
        flexDirection: "row",
        alignItems: "center",
        justifyContent: "space-between",
        gap: 8,
        borderRadius: radius.control,
        borderWidth: 1,
        borderColor: colors.input,
        backgroundColor: colors.background,
        opacity: ctx.disabled() ? 0.5 : 1,
      }}
    >
      <View style={{ flex: 1 }}>{props.children ?? <ComboboxValue />}</View>
      <Text style={{ fontSize: 12, color: colors.mutedForeground }}>▾</Text>
    </View>
  ));
  return <View style={{ width: 0, height: 0 }} />;
}

export function ComboboxValue(props: { placeholder?: string }) {
  const ctx = useCombobox();
  const values = ctx.value() ?? [];
  const label =
    values.length === 0
      ? (props.placeholder ?? ctx.placeholder())
      : values.map((v) => ctx.items.items().find((i) => i.value === v)?.title ?? v).join(", ");

  return (
    <Text
      style={{
        fontSize: 14,
        color: values.length === 0 ? colors.mutedForeground : colors.foreground,
      }}
    >
      {label}
    </Text>
  );
}

export function ComboboxContent(props: { children?: JSX.Element }) {
  const ctx = useCombobox();
  const triggerAccessor = ctx.trigger.get();
  const emptyAccessor = ctx.empty.get();
  const root = ctx.root;

  return (
    <View style={{ gap: 0 }}>
      {props.children}
      <StyledCombobox
        items={ctx.items.items()}
        multiple={root.multiple}
        value={root.value}
        defaultValue={root.defaultValue}
        open={root.open}
        defaultOpen={root.defaultOpen}
        cleanable={root.cleanable}
        disabled={root.disabled}
        placeholder={root.placeholder}
        accessibilityLabel={root.accessibilityLabel}
        trigger={(triggerAccessor?.() as JSX.Element) ?? defaultTrigger(ctx)}
        empty={(emptyAccessor?.() as JSX.Element) ?? root.empty ?? undefined}
        onChange={root.onChange}
        onOpenChange={root.onOpenChange}
      />
    </View>
  );
}

export function ComboboxEmpty(props: { children?: string }) {
  const ctx = useCombobox();
  ctx.empty.set(() => (
    <Text style={{ fontSize: 13, color: colors.mutedForeground, padding: 8 }}>
      {props.children ?? "No results"}
    </Text>
  ));
  return <View style={{ width: 0, height: 0 }} />;
}

export function ComboboxItem(props: { value: string; disabled?: boolean; children?: string }) {
  const ctx = useCombobox();
  ctx.items.register({
    value: props.value,
    title: props.children ?? props.value,
    disabled: props.disabled,
  });
  cleanup(() => ctx.items.unregister(props.value));
  return <View style={{ width: 0, height: 0 }} />;
}

import { signal, type Signal } from "nsh";

/** Controlled/uncontrolled open flag shared by composition roots. */
export type OpenState = {
  open: () => boolean;
  setOpen: (next: boolean, reason?: string) => void;
};

export type OpenChangeEvent<Reason extends string = string> = {
  open: boolean;
  reason: Reason;
};

export function createOpenState<Reason extends string = string>(options: {
  open?: boolean | null;
  defaultOpen?: boolean;
  onOpenChange?: (event: OpenChangeEvent<Reason>) => void;
}): OpenState {
  const uncontrolled = signal(options.defaultOpen ?? false);
  return {
    open: () => (options.open != null ? Boolean(options.open) : uncontrolled()),
    setOpen: (next, reason = "triggerPress") => {
      if (options.open == null) uncontrolled.set(next);
      options.onOpenChange?.({ open: next, reason: reason as Reason });
    },
  };
}

/** Mutable slot filled by a Trigger part before Content reads it. */
export type TriggerSlot = {
  get: () => (() => unknown) | undefined;
  set: (accessor: () => unknown) => void;
};

export function createTriggerSlot(): TriggerSlot {
  let accessor: (() => unknown) | undefined;
  return {
    get: () => accessor,
    set: (next) => {
      accessor = next;
    },
  };
}

export type ItemRegistry<T extends { value: string }> = {
  items: Signal<T[]>;
  register: (item: T) => void;
  unregister: (value: string) => void;
};

export function createItemRegistry<T extends { value: string }>(
  initial: T[] = [],
): ItemRegistry<T> {
  const items = signal<T[]>(initial, { equals: false });
  return {
    items,
    register: (item) => {
      items.update((list) => {
        const next = list.filter((i) => i.value !== item.value);
        next.push(item);
        return next;
      });
    },
    unregister: (value) => {
      items.update((list) => list.filter((i) => i.value !== value));
    },
  };
}
